guide.simple_bytestorage_scripting.examp:
§eImport from a chest§r
§bvar c = side("up");
function tick() { if (c) c.pull(); }§r

§eFeed a group of furnaces§r
(buses with ID "smelters", furnaces on their north side)
§bfunction tick() {
  var f = side("north", "smelters");
  if (f) f.push("minecraft:raw_iron", 16);
}§r

§eCollect from all "inbox" chests§r
§bfunction tick() {
  var i = side("up", "inbox");
  if (i) i.pull();
}§r

§eTwo groups§r
§bfunction tick() {
  var a = side("up", "in"), b = side("up", "out");
  if (a && b) a.move(b);
}§r

§eAuto-craft when low§r
§bfunction tick() {
  if (net.count("minecraft:stick") < 64)
    net.craft("minecraft:stick", 64);
}§r
